class Solution {
  public int maxDistance(String moves) {
    int x = 0, y = 0, blanks = 0;
    for (int i = 0; i < moves.length(); i++) {
      switch (moves.charAt(i)) {
        case 'U':
          y++;
          break;
        case 'D':
          y--;
          break;
        case 'L':
          x--;
          break;
        case 'R':
          x++;
          break;
        default:
          blanks++;
      }
    }
    return Math.abs(x) + Math.abs(y) + blanks;
  }
}
